105	    private void refillListFromModel(List<ParticipantRow> participantRows, TripController fktnController) {
106	        List<Participant> allParticipants = fktnController.getAllParticipants(false);
107	        SumReport sumReport = fktnController.getSumReport();
108	
109	        for (Participant participant : allParticipants) {
110	            ParticipantRow row = new ParticipantRow();
111	            row.setSumPaid(sumReport.getPaymentByUser().get(participant));
112	            row.setSumSpent(sumReport.getSpendingByUser().get(participant));
113	            row.setBalance(sumReport.getBalanceByUser().get(participant));
114	            row.setParticipant(participant);
115	            row.setAmountOfPaymentLines(sumReport.getPaymentByUserCount().get(participant));
116	
117	            participantRows.add(row);
118	        }
119	    }
