122	    private class MyActionModeCallback implements ActionMode.Callback {
123	
124	        private Participant selectedParticipant;
125	
126	        @Override
127	        public boolean onCreateActionMode(ActionMode mode, Menu menu) {
128	            MenuInflater inflater = mode.getMenuInflater();
129	            inflater.inflate(R.menu.options_participant, menu);
130	
131	            menu.setGroupEnabled(R.id.menu_group_participant_active_required, selectedParticipant.isActive());
132	            menu.setGroupEnabled(R.id.menu_group_participant_deletable_required,
133	                    getApp().getTripController().isParticipantDeletable(selectedParticipant));
134	            menu.setGroupEnabled(R.id.menu_group_participant_at_least_another, getApp().getTripController().getAllParticipants(false).size() > 1);
135	
136	            if (selectedParticipant.isActive()) {
137	                menu.removeItem(R.id.option_participant_activate_for_costs);
138	            } else {
139	                menu.removeItem(R.id.option_participant_deactivate_for_costs);
140	            }
141	            return true;
142	        }
143	
144	
145	        @Override
146	        public boolean onPrepareActionMode(ActionMode mode, Menu menu) {
147	            return false;
148	        }
149	
150	        @Override
151	        public boolean onActionItemClicked(ActionMode mode, MenuItem item) {
152	            switch (item.getItemId()) {
153	                case R.id.option_participant_create_payment:
154	                    getApp().getViewController().openCreatePayment(selectedParticipant);
155	                    mode.finish();
156	                    return true;
157	                case R.id.option_participant_create_money_transfer:
158	                    getApp().getViewController().openTransferMoney(selectedParticipant);
159	                    mode.finish();
160	                    return true;
161	                case R.id.option_participant_show_report:
162	                    getApp().getTripController().getDialogState().setParticipantReporting(selectedParticipant);
163	                    ViewPager pager = (ViewPager) getActivity().findViewById(R.id.drawer_content_pager);
164	                    pager.setCurrentItem(Rc.TAB_ID_REPORT);
165	                    mode.finish();
166	                    return true;
167	                case R.id.option_participant_deactivate_for_costs:
168	                    boolean isActive = false;
169	                    setActiveAndPersist(selectedParticipant, isActive);
170	                    adapter.notifyDataSetChanged();
171	                    mode.finish();
172	                    return true;
173	                case R.id.option_participant_activate_for_costs:
174	                    isActive = true;
175	                    setActiveAndPersist(selectedParticipant, isActive);
176	                    adapter.notifyDataSetChanged();
177	                    mode.finish();
178	                    return true;
179	                case R.id.option_participant_edit:
180	                    getApp().getViewController().openEditParticipant(selectedParticipant);
181	                    mode.finish();
182	                    return true;
183	                case R.id.option_participant_delete:
184	                    if (!getApp().getTripController().deleteParticipant(selectedParticipant)) {
185	                        Toast.makeText(getActivity(),
186	                                getResources().getString(R.string.msg_delete_not_possible_inbalance),
187	                                Toast.LENGTH_SHORT)
188	                                .show();
189	                    } else {
190	                        mode.finish();
191	                        updateRows();
192	                    }
193	                    return true;
194	                default:
195	                    return false;
196	            }
197	        }
