210	    private class ShortTabListener implements OnItemClickListener {
211	        public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
212	            if (getRunningActionMode() != null) {
213	                return;
214	            }
215	            TrickyTripperApp app = getApp();
216	            ParticipantRow row = (ParticipantRow) getListView().getItemAtPosition(position);
217	            if (row.getParticipant().isActive()) {
218	                Participant p = row.getParticipant();
219	                app.getViewController().openCreatePayment(p);
220	            }
221	        }
222	    }
