233	    private class LongTabListener implements AdapterView.OnItemLongClickListener {
234	
235	        @Override
236	        public boolean onItemLongClick(AdapterView<?> parent, View view, int position, long id) {
237	            if (getRunningActionMode() != null) {
238	                return false;
239	            }
240	            Participant selection = adapter.getItem(position).getParticipant();
241	            mActionModeCallback.setSelectedParticipant(selection);
242	            AppCompatActivity activity = ((AppCompatActivity) ParticipantTabActivity.this.getActivity());
243	
244	
245	            ActionMode actionMode = activity.startSupportActionMode(mActionModeCallback);
246	            actionMode.setTitle(selection.getName());
247	            setRunningActionMode(actionMode);
248	            view.setSelected(true);
249	            return true;
250	        }
251	    }
